/* SQL utilisateur du 08/11/2026, adapte pour parametres .NET.
   TEST uniquement / MAD / references revalidees / T20 et transport explicite T00 / annee 2026.
   Signature non geree et statuts repris de la requete fournie par l'utilisateur.
   Insertion directe : ne reproduit pas tous les traitements metier X3.
   Appels exclusivement via sob-execute.ps1, pas un script SSMS autonome.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

-- =============== PARAMETRES MODIFIABLES =====================
-- Ne mettre 1 que si APPSOH = Non est confirme pour la societe cible.
-- 4 correspond a 'pas de gestion de signature' dans le dossier TEST observe.
-- Ce commutateur n'est PAS une verification automatique du parametre Sage.
DECLARE @SIGNATURE_NON_GEREE_CONFIRMEE bit = 1; -- admin confirme APPSOH = Non
-- Valeurs observees sur les commandes du client C01401.
-- Elles ne sont PAS des commandes d'activation des boutons UI.
-- Pour un autre client, faire valider son mode de facturation et son solde.
DECLARE @ORDCLE_INITIAL tinyint = 1; -- C01401 : valeur observee sur 14601
DECLARE @MODE_FACTURATION tinyint = (SELECT IME_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT);
DECLARE @TOURNEE tinyint = 1;         -- doit correspondre au param. livraison du client/site
DECLARE @PRIORITE_LIVRAISON tinyint = 1;
DECLARE @REPARTITION_LIGNE tinyint = 2;
DECLARE @STATUT_DEMANDE tinyint = 1;
-- IMPORTANT : une execution repetee peut creer une NOUVELLE commande.
-- Ne pas passer en mode ecriture sans une demande de commande nouvelle.

DECLARE @SOCIETE nvarchar(10) = N'20';
DECLARE @SITE nvarchar(10) = N'201';
DECLARE @TYPE nvarchar(10) = N'SON';
DECLARE @DEVISE nvarchar(6) = (SELECT CUR_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT);
DECLARE @NOM_REP nvarchar(100) = (SELECT REPNAM_0 FROM TEST.SALESREP WHERE REPNUM_0=COALESCE(NULLIF(@REP_CODE,N''),(SELECT REP_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT)));
DECLARE @LUI_MEME tinyint = 1; -- 1 NON, 2 OUI
-- @COMMENTAIRE fourni comme parametre, controle et inclus dans le recapitulatif.
DECLARE @ADRESSE nvarchar(10) = (SELECT BPAADD_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT);
DECLARE @TAUX_TVA decimal(9,5) = 20.0; -- seulement T20 confirme

DROP TABLE IF EXISTS #L;
DROP TABLE IF EXISTS #V;
CREATE TABLE #L (
  LIGNE int NOT NULL PRIMARY KEY,
  ARTICLE nvarchar(40) COLLATE DATABASE_DEFAULT NOT NULL,
  QTY decimal(18,5) NOT NULL,
  PRIX_TTC decimal(18,5) NOT NULL,
  FOURNISSEUR nvarchar(30) COLLATE DATABASE_DEFAULT NOT NULL DEFAULT(N''),
  DESIGNATION nvarchar(140) NULL,
  SAU nvarchar(6) NULL,
  STU nvarchar(6) NULL,
  COE decimal(18,7) NULL,
  TAXE nvarchar(10) COLLATE DATABASE_DEFAULT NULL,
  TAX_OVERRIDE nvarchar(10) COLLATE DATABASE_DEFAULT NULL,
  RATE decimal(9,5) NULL,
  PRIX_HT decimal(18,5) NULL,
  STOMGTCOD tinyint NULL,
  DLVFLG tinyint NULL
);
INSERT #L (LIGNE,ARTICLE,QTY,PRIX_TTC,FOURNISSEUR,TAX_OVERRIDE)
SELECT LIGNE,ARTICLE,QTY,PRIX_TTC,COALESCE(FOURNISSEUR,N''),TAX_OVERRIDE
FROM OPENJSON(@LINES_JSON) WITH (
 LIGNE int '$.line', ARTICLE nvarchar(40) '$.article',
 QTY decimal(18,5) '$.quantity', PRIX_TTC decimal(18,5) '$.price', FOURNISSEUR nvarchar(30) '$.supplier', TAX_OVERRIDE nvarchar(10) '$.tax_code');


DECLARE @REP nvarchar(30), @NUMERO nvarchar(40), @COMPTEUR decimal(25,0),
 @TOTAL_TTC decimal(27,5), @TOTAL_HT decimal(27,5), @TVA decimal(27,5),
 @LOCK int, @T sysname, @Cols nvarchar(max), @Expr nvarchar(max),
 @Sql nvarchar(max), @N int, @NB_REP int,
 @CLIENT_FACTURE nvarchar(30), @CLIENT_PAYEUR nvarchar(30),
 @ADRESSE_PAYEUR nvarchar(10), @BPCGRU nvarchar(30);

BEGIN TRY
 BEGIN TRANSACTION;
 IF DATALENGTH(@REFERENCE)>COL_LENGTH(N'TEST.SORDER',N'CUSORDREF_0')
    THROW 62010,N'Reference trop longue pour le champ Sage.',1;
 IF @DEVISE IS NULL OR @DEVISE<>N'MAD'
    THROW 62002,N'Client absent de TEST ou devise incompatible.',1;
 IF NOT EXISTS(SELECT 1 FROM #L) OR (SELECT COUNT(*) FROM #L)>20
    THROW 62003,N'Nombre de lignes invalide.',1;
 UPDATE #L SET ARTICLE=N'MANTD',QTY=1 WHERE ARTICLE IN(N'TRS',N'TRC',N'MANTD');
 IF @LIVRAISON<@DATE OR @EXPEDITION<>@LIVRAISON
    THROW 62005,N'Date de livraison invalide.',1;
 EXEC @LOCK=sys.sp_getapplock @Resource=@REFERENCE,
      @LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=10000;
 IF @LOCK<0 THROW 62006,N'Verrou de validation non obtenu.',1;
 IF @AUTORISER_ECRITURE=1 AND EXISTS(SELECT 1 FROM TEST.SORDER WHERE CUSORDREF_0=@REFERENCE)
 BEGIN
    IF (SELECT COUNT(*) FROM TEST.SORDER WHERE CUSORDREF_0=@REFERENCE)<>1
       THROW 62007,N'Reference ambigue : controle manuel necessaire.',1;
    IF NOT EXISTS(SELECT 1 FROM TEST.SORDER WHERE CUSORDREF_0=@REFERENCE AND BPCORD_0=@CLIENT)
       THROW 62007,N'Reference utilisee par un autre client.',1;
    SELECT TOP(1) N'ALREADY_CREATED' AS RESULTAT,SOHNUM_0 AS NUMERO_COMMANDE
    FROM TEST.SORDER WHERE CUSORDREF_0=@REFERENCE AND BPCORD_0=@CLIENT;
    COMMIT TRANSACTION;
    RETURN;
 END;

 IF @TYPE <> N'SON' OR @SOCIETE <> N'20' OR @SITE <> N'201' OR YEAR(@DATE) <> 2026
   THROW 61001,N'Numerotation non validee hors SON / societe 20 / site 201 / annee 2026.',1;
 IF @AUTORISER_ECRITURE=1 AND @SIGNATURE_NON_GEREE_CONFIRMEE<>1
   THROW 61023,N'ECRITURE BLOQUEE : confirmer APPSOH=Non pour la societe et activer le commutateur de signature.',1;
 IF @ORDCLE_INITIAL NOT IN(1,2) OR (@MODE_FACTURATION IS NULL OR @MODE_FACTURATION NOT IN(1,6))
   THROW 61024,N'Valeurs d''etat solde ou mode facturation non validees.',1;
 IF @LUI_MEME NOT IN (1,2) THROW 61002,N'Valeur Lui-meme invalide.',1;
 IF (SELECT COUNT(*) FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT)<>1
   THROW 61003,N'Client absent ou ambigu.',1;
 SELECT @CLIENT_FACTURE=NULLIF(BPCINV_0,N''), @CLIENT_PAYEUR=NULLIF(BPCPYR_0,N''),
        @BPCGRU=NULLIF(BPCGRU_0,N'')
 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT;
 SET @CLIENT_FACTURE=COALESCE(@CLIENT_FACTURE,@CLIENT);
 SET @CLIENT_PAYEUR=COALESCE(@CLIENT_PAYEUR,@CLIENT);
 SET @BPCGRU=COALESCE(@BPCGRU,N'');
 -- Ne jamais attribuer aveuglement l'adresse du donneur d'ordre a un payeur different.
 IF @CLIENT_PAYEUR=@CLIENT SET @ADRESSE_PAYEUR=@ADRESSE;
 ELSE
 BEGIN
   SELECT @ADRESSE_PAYEUR=NULLIF(BPAADD_0,N'')
   FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT_PAYEUR;
   IF @ADRESSE_PAYEUR IS NULL OR NOT EXISTS(
      SELECT 1 FROM TEST.BPADDRESS
      WHERE BPANUM_0=@CLIENT_PAYEUR AND BPAADD_0=@ADRESSE_PAYEUR)
      THROW 61025,N'Adresse du payeur non trouvee. Controle manuel necessaire.',1;
 END;
 IF (SELECT COUNT(*) FROM TEST.BPADDRESS WHERE BPANUM_0=@CLIENT AND BPAADD_0=@ADRESSE)<>1
   THROW 61004,N'Adresse AD1 introuvable.',1;
 IF NOT EXISTS (SELECT 1 FROM TEST.FACILITY WHERE FCY_0=@SITE)
   THROW 61005,N'Site introuvable.',1;
 SELECT @NB_REP=COUNT(*),@REP=MAX(REPNUM_0) FROM TEST.SALESREP
 WHERE UPPER(REPLACE(LTRIM(RTRIM(REPNAM_0)),N'_',N' '))=UPPER(@NOM_REP);
 IF @NB_REP<>1 THROW 61006,N'Representant introuvable ou ambigu.',1;
 IF EXISTS(SELECT 1 FROM #L WHERE QTY<=0 OR PRIX_TTC<0)
   THROW 61007,N'Quantite ou prix invalide.',1;
 -- =============================================================
 -- CONTROLE FOURNISSEUR PAR ARTICLE - AVANT TOUT INSERT SAGE
 -- '' signifie : aucun fournisseur choisi pour cet article.
 -- Le fournisseur renseigne doit exister ET etre lie a l'article
 -- dans TEST.ITMBPS (fiche Articles-Fournisseurs Sage X3).
 -- Aucun INSERT dans BPSUPPLIER ni dans ITMBPS.
 -- =============================================================
 IF OBJECT_ID(N'TEST.ITMBPS',N'U') IS NULL
   THROW 61018,N'Table TEST.ITMBPS absente : verification fournisseur impossible.',1;
 IF COL_LENGTH(N'TEST.ITMBPS',N'BPSNUM_0') IS NULL
    OR COL_LENGTH(N'TEST.ITMBPS',N'ITMREF_0') IS NULL
   THROW 61019,N'Colonnes ITMBPS.BPSNUM_0 ou ITMREF_0 absentes.',1;
 IF OBJECT_ID(N'TEST.BPSUPPLIER',N'U') IS NULL
   THROW 61020,N'Table TEST.BPSUPPLIER absente : verification fournisseur impossible.',1;
 IF EXISTS (
   SELECT 1 FROM #L L
   WHERE NULLIF(LTRIM(RTRIM(L.FOURNISSEUR)),N'') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM TEST.BPSUPPLIER B
       WHERE B.BPSNUM_0 COLLATE DATABASE_DEFAULT = L.FOURNISSEUR COLLATE DATABASE_DEFAULT
     )
 )
 BEGIN
   SELECT L.LIGNE,L.ARTICLE,L.FOURNISSEUR,
          N'FOURNISSEUR INEXISTANT DANS TEST.BPSUPPLIER' AS ERREUR
   FROM #L L
   WHERE NULLIF(LTRIM(RTRIM(L.FOURNISSEUR)),N'') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM TEST.BPSUPPLIER B
       WHERE B.BPSNUM_0 COLLATE DATABASE_DEFAULT = L.FOURNISSEUR COLLATE DATABASE_DEFAULT
     );
   THROW 61021,N'Un fournisseur indique nexiste pas : creation annulee.',1;
 END;
 IF EXISTS (
   SELECT 1 FROM #L L
   WHERE NULLIF(LTRIM(RTRIM(L.FOURNISSEUR)),N'') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM TEST.ITMBPS AB
       WHERE AB.ITMREF_0 COLLATE DATABASE_DEFAULT = L.ARTICLE COLLATE DATABASE_DEFAULT
         AND AB.BPSNUM_0 COLLATE DATABASE_DEFAULT = L.FOURNISSEUR COLLATE DATABASE_DEFAULT
     )
 )
 BEGIN
   SELECT L.LIGNE,L.ARTICLE,L.FOURNISSEUR,
          N'FOURNISSEUR NON LIE A CET ARTICLE DANS TEST.ITMBPS' AS ERREUR
   FROM #L L
   WHERE NULLIF(LTRIM(RTRIM(L.FOURNISSEUR)),N'') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM TEST.ITMBPS AB
       WHERE AB.ITMREF_0 COLLATE DATABASE_DEFAULT = L.ARTICLE COLLATE DATABASE_DEFAULT
         AND AB.BPSNUM_0 COLLATE DATABASE_DEFAULT = L.FOURNISSEUR COLLATE DATABASE_DEFAULT
     );
   THROW 61022,N'Fournisseur non lie a la fiche article : creation annulee.',1;
 END;

 IF EXISTS(SELECT 1 FROM #L L LEFT JOIN TEST.ITMMASTER I ON I.ITMREF_0=L.ARTICLE COLLATE DATABASE_DEFAULT
   LEFT JOIN TEST.ITMFACILIT F ON F.ITMREF_0=L.ARTICLE COLLATE DATABASE_DEFAULT AND F.STOFCY_0=@SITE
   WHERE I.ITMREF_0 IS NULL OR F.ITMREF_0 IS NULL)
   THROW 61008,N'Article absent ou non rattache au site.',1;
 IF EXISTS(SELECT 1 FROM #L WHERE TAX_OVERRIDE IS NOT NULL AND (TAX_OVERRIDE<>N'T00' OR ARTICLE<>N'MANTD'))
   THROW 62011,N'Exoneration autorisee uniquement sur transport MANTD.',1;
 IF EXISTS(SELECT 1 FROM #L WHERE TAX_OVERRIDE=N'T00') AND NOT EXISTS(SELECT 1 FROM TEST.TABVAT WHERE VAT_0=N'T00' AND VATRAT_0=0)
   THROW 62012,N'Taxe T00 taux zero absente du parametrage TEST.',1;
 UPDATE L SET DESIGNATION=I.ITMDES1_0, SAU=I.SAU_0,STU=I.STU_0,
   COE=I.SAUSTUCOE_0,TAXE=COALESCE(L.TAX_OVERRIDE,I.VACITM_0), DLVFLG=I.DLVFLG_0, STOMGTCOD=I.STOMGTCOD_0,
   RATE=CASE WHEN L.TAX_OVERRIDE=N'T00' THEN 0 ELSE @TAUX_TVA END,
   PRIX_HT=ROUND(L.PRIX_TTC/(1+CASE WHEN L.TAX_OVERRIDE=N'T00' THEN 0 ELSE @TAUX_TVA END/100),5)
 FROM #L L JOIN TEST.ITMMASTER I ON I.ITMREF_0=L.ARTICLE COLLATE DATABASE_DEFAULT;
 IF EXISTS(SELECT 1 FROM #L WHERE STOMGTCOD NOT IN(1,2,3) OR STOMGTCOD IS NULL OR TAXE NOT IN(N'T20',N'T00') OR TAXE IS NULL
    OR NULLIF(SAU,N'') IS NULL OR NULLIF(STU,N'') IS NULL OR COE<=0 OR COE IS NULL OR DLVFLG<>2 OR DLVFLG IS NULL)
   THROW 61009,N'Unite ou niveau de taxe autre que T20 : transaction bloquee.',1;
 SELECT @TOTAL_TTC=SUM(ROUND(QTY*PRIX_TTC,2)),
        @TOTAL_HT=SUM(ROUND(QTY*PRIX_TTC/(1+RATE/100),2)) FROM #L;
 SET @TVA=@TOTAL_TTC-@TOTAL_HT;
 CREATE TABLE #V(TAXE nvarchar(10) COLLATE DATABASE_DEFAULT, RATE decimal(9,5), BASE_HT decimal(27,5), TAX_AMOUNT decimal(27,5));
 INSERT #V SELECT TAXE,RATE,SUM(ROUND(QTY*PRIX_TTC/(1+RATE/100),2)),SUM(ROUND(QTY*PRIX_TTC,2))-SUM(ROUND(QTY*PRIX_TTC/(1+RATE/100),2)) FROM #L GROUP BY TAXE,RATE;

 IF @TOTAL_TTC_ATTENDU IS NOT NULL AND @TOTAL_TTC<>@TOTAL_TTC_ATTENDU
   THROW 61010,N'Total TTC different du total attendu.',1;

 -- La simulation est le mode par défaut. Rien n'est écrit dans Sage.
 IF EXISTS(SELECT 1 FROM (VALUES (N'SORDER',N'ALLSTA_0'),(N'SORDER',N'ALLTYP_0'),(N'SORDER',N'AMTTAX_0'),(N'SORDER',N'APPFLG_0'),(N'SORDER',N'BASTAX_0'),(N'SORDER',N'BPAADD_0'),(N'SORDER',N'BPAPYR_0'),(N'SORDER',N'BPCCTY_0'),(N'SORDER',N'BPCGRU_0'),(N'SORDER',N'BPCINV_0'),(N'SORDER',N'BPCNAM_0'),(N'SORDER',N'BPCORD_0'),(N'SORDER',N'BPCPYR_0'),(N'SORDER',N'CHGRAT_0'),(N'SORDER',N'CHGTYP_0'),(N'SORDER',N'CPY_0'),(N'SORDER',N'CUR_0'),(N'SORDER',N'CUSORDREF_0'),(N'SORDER',N'DEMDLVDAT_0'),(N'SORDER',N'DIE_0'),(N'SORDER',N'DIE_1'),(N'SORDER',N'DLRATI_0'),(N'SORDER',N'DLRNOT_0'),(N'SORDER',N'DLVPIO_0'),(N'SORDER',N'DLVSTA_0'),(N'SORDER',N'DME_0'),(N'SORDER',N'DRN_0'),(N'SORDER',N'HLDSTA_0'),(N'SORDER',N'IME_0'),(N'SORDER',N'INRATI_0'),(N'SORDER',N'INRNOT_0'),(N'SORDER',N'INVSTA_0'),(N'SORDER',N'LINNBR_0'),(N'SORDER',N'ODL_0'),(N'SORDER',N'ORDATIL_0'),(N'SORDER',N'ORDATI_0'),(N'SORDER',N'ORDCLE_0'),(N'SORDER',N'ORDDAT_0'),(N'SORDER',N'ORDINVATIL_0'),(N'SORDER',N'ORDINVATI_0'),(N'SORDER',N'ORDINVNOTL_0'),(N'SORDER',N'ORDINVNOT_0'),(N'SORDER',N'ORDNOTL_0'),(N'SORDER',N'ORDNOT_0'),(N'SORDER',N'ORDSTA_0'),(N'SORDER',N'PRITYP_0'),(N'SORDER',N'PTE_0'),(N'SORDER',N'REP_0'),(N'SORDER',N'REP_1'),(N'SORDER',N'SALFCY_0'),(N'SORDER',N'SHIDAT_0'),(N'SORDER',N'SOHCAT_0'),(N'SORDER',N'SOHNUM_0'),(N'SORDER',N'SOHTYP_0'),(N'SORDER',N'STOFCY_0'),(N'SORDER',N'VACBPR_0'),(N'SORDER',N'XCOMM_0'),(N'SORDER',N'XLUIMEM_0'),(N'SORDERP',N'BPAADD_0'),(N'SORDERP',N'BPCINV_0'),(N'SORDERP',N'BPCORD_0'),(N'SORDERP',N'CPY_0'),(N'SORDERP',N'FOCFLG_0'),(N'SORDERP',N'GROPRI_0'),(N'SORDERP',N'ITMDES1_0'),(N'SORDERP',N'ITMDES_0'),(N'SORDERP',N'ITMREF_0'),(N'SORDERP',N'LINTYP_0'),(N'SORDERP',N'NETPRIATI_0'),(N'SORDERP',N'NETPRINOT_0'),(N'SORDERP',N'NETPRI_0'),(N'SORDERP',N'REP1_0'),(N'SORDERP',N'REP2_0'),(N'SORDERP',N'SALFCY_0'),(N'SORDERP',N'SAUSTUCOE_0'),(N'SORDERP',N'SAU_0'),(N'SORDERP',N'SOHCAT_0'),(N'SORDERP',N'SOHNUM_0'),(N'SORDERP',N'SOPLIN_0'),(N'SORDERP',N'SOPSEQ_0'),(N'SORDERP',N'SOQSTA_0'),(N'SORDERP',N'STOFCY_0'),(N'SORDERP',N'STU_0'),(N'SORDERP',N'VACITM_0'),(N'SORDERP',N'VAT_0'),(N'SORDERQ',N'ALLTYP_0'),(N'SORDERQ',N'BPAADD_0'),(N'SORDERQ',N'BPCORD_0'),(N'SORDERQ',N'CPY_0'),(N'SORDERQ',N'DEMDLVDAT_0'),(N'SORDERQ',N'EXTDLVDAT_0'),(N'SORDERQ',N'DEMSTA_0'),(N'SORDERQ',N'DLVFLG_0'),(N'SORDERQ',N'DLVPIO_0'),(N'SORDERQ',N'DRN_0'),(N'SORDERQ',N'DSPLINFLG_0'),(N'SORDERQ',N'INVFLG_0'),(N'SORDERQ',N'ITMREF_0'),(N'SORDERQ',N'ORDDAT_0'),(N'SORDERQ',N'ORIQTY_0'),(N'SORDERQ',N'QTYSTU_0'),(N'SORDERQ',N'QTY_0'),(N'SORDERQ',N'SALFCY_0'),(N'SORDERQ',N'SHIDAT_0'),(N'SORDERQ',N'SOHCAT_0'),(N'SORDERQ',N'SOHNUM_0'),(N'SORDERQ',N'SOPLIN_0'),(N'SORDERQ',N'SOQSEQ_0'),(N'SORDERQ',N'SOQSTA_0'),(N'SORDERQ',N'STOFCY_0'),(N'SORDERQ',N'STOMGTCOD_0'),(N'SORDERQ',N'XBPS_0'),(N'SVCRVAT',N'AMTTAX_0'),(N'SVCRVAT',N'BASTAX_0'),(N'SVCRVAT',N'CPY_0'),(N'SVCRVAT',N'CUR_0'),(N'SVCRVAT',N'EXEAMTTAX_0'),(N'SVCRVAT',N'THEAMTTAX_0'),(N'SVCRVAT',N'VATAMT_0'),(N'SVCRVAT',N'VATGRO_0'),(N'SVCRVAT',N'VATNET_0'),(N'SVCRVAT',N'VATRAT_0'),(N'SVCRVAT',N'VAT_0'),(N'SVCRVAT',N'VCRNUM_0'),(N'SVCRVAT',N'VCRTYP_0')) M(TAB,COL)
 WHERE NOT EXISTS(SELECT 1 FROM sys.columns C
 WHERE C.object_id=OBJECT_ID(N'TEST.'+M.TAB) AND C.name=M.COL))
   THROW 62009,N'Une colonne requise est absente : controle du schema impossible.',1;
 DECLARE @PLAN nvarchar(max)=(SELECT
 @COMMENTAIRE AS comment,@CLIENT AS client,@SOCIETE AS company,@SITE AS site,@TYPE AS order_type,
 @DATE AS order_date,@LIVRAISON AS delivery,@EXPEDITION AS shipment,
 @DEVISE AS currency,@REP AS rep,@ADRESSE AS address,
 @CLIENT_FACTURE AS invoice_client,@CLIENT_PAYEUR AS payer,@ADRESSE_PAYEUR AS payer_address,
 @BPCGRU AS customer_group,@MODE_FACTURATION AS billing_mode,@ORDCLE_INITIAL AS closed_state,
 @TOURNEE AS route,@PRIORITE_LIVRAISON AS delivery_priority,
 @TOTAL_HT AS ht,@TVA AS vat,@TOTAL_TTC AS ttc,
 JSON_QUERY((SELECT LIGNE,ARTICLE,QTY,PRIX_TTC,DESIGNATION,SAU,STU,COE,TAXE,PRIX_HT,DLVFLG,STOMGTCOD,NULLIF(FOURNISSEUR,N'') AS FOURNISSEUR
 FROM #L ORDER BY LIGNE FOR JSON PATH)) AS lines,
 JSON_QUERY((SELECT BPCNUM_0,BPCNAM_0,PTE_0,VACBPR_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT FOR JSON PATH)) AS customer,
 JSON_QUERY((SELECT * FROM TEST.BPADDRESS WHERE BPANUM_0=@CLIENT AND BPAADD_0=@ADRESSE FOR JSON PATH)) AS address_details
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 IF @AUTORISER_ECRITURE=1 AND (@EXPECTED_PLAN IS NULL OR CONVERT(varbinary(max),@EXPECTED_PLAN)<>CONVERT(varbinary(max),@PLAN))
   THROW 62008,N'Les donnees Sage ont change. Refaire le recapitulatif avant validation.',1;
 IF @AUTORISER_ECRITURE=0
 BEGIN
   SELECT N'PREVIEW' AS RESULTAT,@PLAN AS PLAN_JSON;
   ROLLBACK TRANSACTION;
   RETURN;
 END;
 IF @AUTORISER_ECRITURE=0
 BEGIN
   SELECT N'SIMULATION - AUCUNE ECRITURE SAGE' AS RESULTAT,
      @CLIENT AS CLIENT,@REP AS CODE_COMMERCIAL,@TOTAL_HT AS HT,@TVA AS TVA,@TOTAL_TTC AS TTC;
   SELECT LIGNE,ARTICLE,QTY,SAU,PRIX_TTC,PRIX_HT,TAXE,FOURNISSEUR FROM #L ORDER BY LIGNE;
   ROLLBACK TRANSACTION;
 END
 ELSE
 BEGIN
   /*
     ATTENTION : CES INSERTS SONT TECHNIQUES, PAS UNE CREATION X3 CERTIFIEE.
     Ils initialisent les colonnes non cartographiees à 0 / chaîne vide /
     date historique, ce qui peut violer des invariants métier non connus.
   */
   EXEC @LOCK=sys.sp_getapplock @Resource=N'X3_TEST_SON_20_2026',
        @LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=10000;
   IF @LOCK<0 THROW 61011,N'Verrou non obtenu.',1;
   SELECT @COMPTEUR=VALEUR_0 FROM TEST.AVALNUM WITH (UPDLOCK,HOLDLOCK)
   WHERE CODNUM_0=@TYPE AND SITE_0=@SOCIETE AND PERIODE_0=26;
   IF @COMPTEUR IS NULL THROW 61012,N'Compteur SON non trouve.',1;
   SET @NUMERO=N'2026ARC'+CONVERT(nvarchar(20),@COMPTEUR);
   IF EXISTS(SELECT 1 FROM TEST.SORDER WITH(UPDLOCK,HOLDLOCK) WHERE SOHNUM_0=@NUMERO)
      THROW 61013,N'Numero deja present.',1;

   CREATE TABLE #M (TAB sysname COLLATE DATABASE_DEFAULT NOT NULL, COL sysname COLLATE DATABASE_DEFAULT NOT NULL, EXPR nvarchar(max) NOT NULL);
   INSERT #M VALUES
   -- Champs communs
   (N'SORDER',N'SOHNUM_0',N'@NUMERO'),(N'SORDERP',N'SOHNUM_0',N'@NUMERO'),(N'SORDERQ',N'SOHNUM_0',N'@NUMERO'),
   (N'SVCRVAT',N'VCRNUM_0',N'@NUMERO'),
   (N'SORDER',N'CPY_0',N'@SOCIETE'),(N'SORDERP',N'CPY_0',N'@SOCIETE'),(N'SORDERQ',N'CPY_0',N'@SOCIETE'),(N'SVCRVAT',N'CPY_0',N'@SOCIETE'),
   (N'SORDER',N'BPCORD_0',N'@CLIENT'),(N'SORDERP',N'BPCORD_0',N'@CLIENT'),(N'SORDERQ',N'BPCORD_0',N'@CLIENT'),
   (N'SORDER',N'CUR_0',N'@DEVISE'),(N'SVCRVAT',N'CUR_0',N'@DEVISE'),
   (N'SORDER',N'SALFCY_0',N'@SITE'),(N'SORDERP',N'SALFCY_0',N'@SITE'),(N'SORDERQ',N'SALFCY_0',N'@SITE'),
   (N'SORDER',N'STOFCY_0',N'@SITE'),(N'SORDERP',N'STOFCY_0',N'@SITE'),(N'SORDERQ',N'STOFCY_0',N'@SITE'),
   (N'SORDER',N'BPAADD_0',N'@ADRESSE'),(N'SORDERP',N'BPAADD_0',N'@ADRESSE'),(N'SORDERQ',N'BPAADD_0',N'@ADRESSE'),
   (N'SORDER',N'ORDDAT_0',N'CAST(@DATE AS datetime)'),(N'SORDERQ',N'ORDDAT_0',N'CAST(@DATE AS datetime)'),
   (N'SORDER',N'DEMDLVDAT_0',N'CAST(@LIVRAISON AS datetime)'),(N'SORDERQ',N'DEMDLVDAT_0',N'CAST(@LIVRAISON AS datetime)'),
   (N'SORDERQ',N'EXTDLVDAT_0',N'CAST(@LIVRAISON AS datetime)'),
   (N'SORDER',N'SHIDAT_0',N'CAST(@EXPEDITION AS datetime)'),(N'SORDERQ',N'SHIDAT_0',N'CAST(@EXPEDITION AS datetime)'),
   -- En-tete : valeurs metier constatees sur TEST, et non reglage des boutons UI.
   -- Signature 4 UNIQUEMENT dans le cas APPSOH = Non, confirme par admin.
   (N'SORDER',N'SOHTYP_0',N'@TYPE'),(N'SORDER',N'SOHCAT_0',N'1'),
   (N'SORDER',N'BPCINV_0',N'@CLIENT_FACTURE'),
   (N'SORDER',N'BPCPYR_0',N'@CLIENT_PAYEUR'),
   (N'SORDER',N'BPAPYR_0',N'@ADRESSE_PAYEUR'),
   (N'SORDER',N'BPCGRU_0',N'@BPCGRU'),
   (N'SORDER',N'BPCNAM_0',N'(SELECT BPCNAM_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT)'),
   (N'SORDER',N'BPCCTY_0',N'(SELECT CTY_0 FROM TEST.BPADDRESS WHERE BPANUM_0=@CLIENT AND BPAADD_0=@ADRESSE)'),
   (N'SORDER',N'PTE_0',N'(SELECT PTE_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT)'),
   (N'SORDER',N'VACBPR_0',N'(SELECT VACBPR_0 FROM TEST.BPCUSTOMER WHERE BPCNUM_0=@CLIENT)'),
   (N'SORDER',N'REP_0',N'@REP'),(N'SORDER',N'REP_1',N'N'''''),
   (N'SORDER',N'PRITYP_0',N'2'),(N'SORDER',N'CUSORDREF_0',N'@REFERENCE'),
   (N'SORDER',N'XCOMM_0',N'@COMMENTAIRE'),(N'SORDER',N'XLUIMEM_0',N'@LUI_MEME'),
   (N'SORDER',N'CHGRAT_0',N'1'),
   -- CHGTYP=0 a ete observe pour C01401 ; autre valeur possible selon client/devise.
   (N'SORDER',N'CHGTYP_0',N'0'),
   (N'SORDER',N'DRN_0',N'@TOURNEE'),(N'SORDER',N'DLVPIO_0',N'@PRIORITE_LIVRAISON'),
   (N'SORDER',N'ODL_0',N'1'),(N'SORDER',N'DME_0',N'1'),
   -- Mode de facturation du client : ne pas forcer 6 pour griser Proforma.
   (N'SORDER',N'IME_0',N'@MODE_FACTURATION'),
   (N'SORDER',N'ALLTYP_0',N'1'),(N'SORDER',N'ALLSTA_0',N'1'),
   -- Etat de solde : ne pas forcer 2 pour griser Allocation.
   (N'SORDER',N'HLDSTA_0',N'1'),(N'SORDER',N'ORDCLE_0',N'@ORDCLE_INITIAL'),
   (N'SORDER',N'APPFLG_0',N'4'),
   (N'SORDER',N'DIE_0',N'N''AX1'''),(N'SORDER',N'DIE_1',N'N''AX2'''),
   (N'SORDER',N'LINNBR_0',N'(SELECT COUNT(*) FROM #L)'),
   (N'SORDER',N'ORDNOT_0',N'@TOTAL_HT'),(N'SORDER',N'ORDATI_0',N'@TOTAL_TTC'),
   (N'SORDER',N'ORDNOTL_0',N'@TOTAL_HT'),(N'SORDER',N'ORDATIL_0',N'@TOTAL_TTC'),
   (N'SORDER',N'ORDINVNOT_0',N'@TOTAL_HT'),(N'SORDER',N'ORDINVATI_0',N'@TOTAL_TTC'),
   (N'SORDER',N'ORDINVNOTL_0',N'@TOTAL_HT'),(N'SORDER',N'ORDINVATIL_0',N'@TOTAL_TTC'),
   (N'SORDER',N'DLRNOT_0',N'@TOTAL_HT'),(N'SORDER',N'DLRATI_0',N'@TOTAL_TTC'),
   (N'SORDER',N'INRNOT_0',N'@TOTAL_HT'),(N'SORDER',N'INRATI_0',N'@TOTAL_TTC'),
   (N'SORDER',N'AMTTAX_0',N'@TVA'),(N'SORDER',N'BASTAX_0',N'@TOTAL_HT'),
   (N'SORDER',N'ORDSTA_0',N'1'),(N'SORDER',N'DLVSTA_0',N'1'),(N'SORDER',N'INVSTA_0',N'1'),
   -- Prix / ligne
   (N'SORDERP',N'SOPLIN_0',N'L.LIGNE'),(N'SORDERP',N'SOPSEQ_0',N'L.LIGNE'),
   (N'SORDERP',N'SOHCAT_0',N'1'),(N'SORDERP',N'BPCINV_0',N'@CLIENT_FACTURE'),
   (N'SORDERP',N'ITMREF_0',N'L.ARTICLE'),(N'SORDERP',N'ITMDES1_0',N'L.DESIGNATION'),
   (N'SORDERP',N'ITMDES_0',N'L.DESIGNATION'),(N'SORDERP',N'VACITM_0',N'L.TAXE'),
   (N'SORDERP',N'VAT_0',N'L.TAXE'),(N'SORDERP',N'REP1_0',N'@REP'),(N'SORDERP',N'REP2_0',N'N'''''),
   (N'SORDERP',N'GROPRI_0',N'L.PRIX_TTC'),(N'SORDERP',N'NETPRI_0',N'L.PRIX_TTC'),
   (N'SORDERP',N'NETPRIATI_0',N'L.PRIX_TTC'),(N'SORDERP',N'NETPRINOT_0',N'L.PRIX_HT'),
   (N'SORDERP',N'SAU_0',N'L.SAU'),(N'SORDERP',N'STU_0',N'L.STU'),
   (N'SORDERP',N'SAUSTUCOE_0',N'L.COE'),(N'SORDERP',N'SOQSTA_0',N'1'),
   (N'SORDERP',N'LINTYP_0',N'1'),(N'SORDERP',N'FOCFLG_0',N'1'),
   -- Quantites / ligne
   (N'SORDERQ',N'SOPLIN_0',N'L.LIGNE'),(N'SORDERQ',N'SOQSEQ_0',N'L.LIGNE'),
   (N'SORDERQ',N'SOHCAT_0',N'1'),(N'SORDERQ',N'ITMREF_0',N'L.ARTICLE'),
   (N'SORDERQ',N'QTY_0',N'L.QTY'),(N'SORDERQ',N'ORIQTY_0',N'L.QTY'),
   (N'SORDERQ',N'QTYSTU_0',N'L.QTY*L.COE'),(N'SORDERQ',N'XBPS_0',N'COALESCE(NULLIF(LTRIM(RTRIM(L.FOURNISSEUR)),N''''),N'''')'),
   (N'SORDERQ',N'SOQSTA_0',N'1'),
   (N'SORDERQ',N'DLVFLG_0',N'L.DLVFLG'),
   (N'SORDERQ',N'INVFLG_0',N'1'),
   (N'SORDERQ',N'STOMGTCOD_0',N'L.STOMGTCOD'), -- observe pour RAB*/CPJ45 ; confirmer sur autre article
   (N'SORDERQ',N'ALLTYP_0',N'1'),
   (N'SORDERQ',N'DEMSTA_0',N'@STATUT_DEMANDE'),
   (N'SORDERQ',N'DSPLINFLG_0',N'@REPARTITION_LIGNE'),
   (N'SORDERQ',N'DRN_0',N'@TOURNEE'),
   (N'SORDERQ',N'DLVPIO_0',N'@PRIORITE_LIVRAISON'),
   -- Fiscalité par groupe T20 et transport exonere T00
   (N'SVCRVAT',N'VCRTYP_0',N'20'),(N'SVCRVAT',N'VAT_0',N'V.TAXE'),
   (N'SVCRVAT',N'VATRAT_0',N'V.RATE'),(N'SVCRVAT',N'BASTAX_0',N'V.BASE_HT'),
   (N'SVCRVAT',N'AMTTAX_0',N'V.TAX_AMOUNT'),(N'SVCRVAT',N'THEAMTTAX_0',N'V.TAX_AMOUNT'),
   (N'SVCRVAT',N'EXEAMTTAX_0',N'V.TAX_AMOUNT'),(N'SVCRVAT',N'VATAMT_0',N'V.TAX_AMOUNT'),
   (N'SVCRVAT',N'VATGRO_0',N'V.BASE_HT'),(N'SVCRVAT',N'VATNET_0',N'V.BASE_HT');

   -- Détection de colonnes requises par la configuration mais absentes.
   IF EXISTS(SELECT 1 FROM #M M WHERE NOT EXISTS(
      SELECT 1 FROM sys.columns C WHERE C.object_id=OBJECT_ID(N'TEST.'+M.TAB) AND C.name COLLATE DATABASE_DEFAULT=M.COL COLLATE DATABASE_DEFAULT))
      THROW 61014,N'Une colonne attendue est absente du schema TEST.',1;

   SET @N=1;
   WHILE @N<=4
   BEGIN
      SET @T=CASE @N WHEN 1 THEN N'SORDER' WHEN 2 THEN N'SORDERP'
                     WHEN 3 THEN N'SORDERQ' ELSE N'SVCRVAT' END;
      SELECT @Cols=STRING_AGG(CONVERT(nvarchar(max),QUOTENAME(C.name)),N',')
                   WITHIN GROUP(ORDER BY C.column_id),
             @Expr=STRING_AGG(CONVERT(nvarchar(max),
                  COALESCE(M.EXPR,
                    CASE WHEN C.name=N'AUUID_0' THEN N'CONVERT(binary(16),NEWID())'
                         WHEN C.name=N'UPDTICK_0' THEN N'1'
                         WHEN C.name IN(N'CREDATTIM_0',N'UPDDATTIM_0') THEN N'GETDATE()'
                         WHEN C.name IN(N'CREDAT_0',N'UPDDAT_0') THEN N'CAST(@DATE AS datetime)'
                         WHEN TY.name IN(N'datetime',N'date',N'datetime2',N'smalldatetime') THEN N'CONVERT(datetime,''17530101'',112)'
                         WHEN TY.name IN(N'nvarchar',N'varchar',N'nchar',N'char') THEN NCHAR(78)+REPLICATE(NCHAR(39),2)
                         WHEN TY.name IN(N'numeric',N'decimal',N'int',N'bigint',N'smallint',N'tinyint',N'bit',N'float',N'real') THEN N'0'
                         WHEN TY.name IN(N'binary',N'varbinary') THEN N'CONVERT(binary(16),0)'
                         ELSE N'NULL' END)),N',')
                   WITHIN GROUP(ORDER BY C.column_id)
      FROM sys.columns C JOIN sys.types TY ON TY.user_type_id=C.user_type_id
      LEFT JOIN #M M ON M.TAB COLLATE DATABASE_DEFAULT=@T COLLATE DATABASE_DEFAULT AND M.COL COLLATE DATABASE_DEFAULT=C.name COLLATE DATABASE_DEFAULT
      WHERE C.object_id=OBJECT_ID(N'TEST.'+@T) AND C.is_identity=0 AND C.is_computed=0;
      -- L'absence de mappage d'un champ métier obligatoire ne peut pas être
      -- validée par la seule contrainte NOT NULL.
      SET @Sql=N'INSERT INTO TEST.'+QUOTENAME(@T)+N' ('+@Cols+N') SELECT '+@Expr
           + CASE WHEN @T IN(N'SORDERP',N'SORDERQ') THEN N' FROM #L L;' WHEN @T=N'SVCRVAT' THEN N' FROM #V V;' ELSE N';' END;
      EXEC sys.sp_executesql @Sql,
         N'@NUMERO nvarchar(40),@CLIENT nvarchar(30),@SOCIETE nvarchar(10),@SITE nvarchar(10),@TYPE nvarchar(10),@DEVISE nvarchar(6),@REP nvarchar(30),@DATE date,@LIVRAISON date,@EXPEDITION date,@ADRESSE nvarchar(10),@LUI_MEME tinyint,@REFERENCE nvarchar(40),@COMMENTAIRE nvarchar(200),@TOTAL_HT decimal(27,5),@TOTAL_TTC decimal(27,5),@TVA decimal(27,5),@TAUX_TVA decimal(9,5),@CLIENT_FACTURE nvarchar(30),@CLIENT_PAYEUR nvarchar(30),@ADRESSE_PAYEUR nvarchar(10),@BPCGRU nvarchar(30),@ORDCLE_INITIAL tinyint,@MODE_FACTURATION tinyint,@TOURNEE tinyint,@PRIORITE_LIVRAISON tinyint,@REPARTITION_LIGNE tinyint,@STATUT_DEMANDE tinyint',
         @NUMERO,@CLIENT,@SOCIETE,@SITE,@TYPE,@DEVISE,@REP,@DATE,@LIVRAISON,@EXPEDITION,@ADRESSE,@LUI_MEME,@REFERENCE,@COMMENTAIRE,@TOTAL_HT,@TOTAL_TTC,@TVA,@TAUX_TVA,@CLIENT_FACTURE,@CLIENT_PAYEUR,@ADRESSE_PAYEUR,@BPCGRU,@ORDCLE_INITIAL,@MODE_FACTURATION,@TOURNEE,@PRIORITE_LIVRAISON,@REPARTITION_LIGNE,@STATUT_DEMANDE;
      SET @N=@N+1;
   END;
   IF (SELECT COUNT(*) FROM TEST.SORDER WHERE SOHNUM_0=@NUMERO AND BPCORD_0=@CLIENT)<>1
      OR (SELECT COUNT(*) FROM TEST.SORDERP WHERE SOHNUM_0=@NUMERO)<>(SELECT COUNT(*) FROM #L)
      OR (SELECT COUNT(*) FROM TEST.SORDERQ WHERE SOHNUM_0=@NUMERO)<>(SELECT COUNT(*) FROM #L)
      OR (SELECT COUNT(*) FROM TEST.SVCRVAT WHERE VCRNUM_0=@NUMERO AND VCRTYP_0=20)<>(SELECT COUNT(*) FROM #V)
      THROW 61015,N'Controle apres insertion echoue.',1;
   IF EXISTS(SELECT 1 FROM #L L WHERE NOT EXISTS(
       SELECT 1 FROM TEST.SORDERQ Q JOIN TEST.SORDERP P ON P.SOHNUM_0=Q.SOHNUM_0
       AND P.SOPLIN_0=Q.SOPLIN_0 AND P.SOPSEQ_0=Q.SOQSEQ_0
       WHERE Q.SOHNUM_0=@NUMERO AND Q.SOPLIN_0=L.LIGNE AND Q.ITMREF_0=L.ARTICLE COLLATE DATABASE_DEFAULT
       AND Q.QTY_0=L.QTY AND P.NETPRIATI_0=L.PRIX_TTC))
      THROW 61016,N'Controle prix et quantites echoue.',1;
   IF EXISTS(
      SELECT 1 FROM TEST.SORDERQ Q JOIN #L L ON L.LIGNE=Q.SOPLIN_0
      WHERE Q.SOHNUM_0=@NUMERO
        AND (Q.DLVFLG_0<>L.DLVFLG OR Q.DEMSTA_0<>@STATUT_DEMANDE
          OR Q.DEMDLVDAT_0 IS NULL OR Q.DEMDLVDAT_0<>CAST(@LIVRAISON AS datetime)
          OR Q.EXTDLVDAT_0 IS NULL OR Q.EXTDLVDAT_0<>CAST(@LIVRAISON AS datetime)
          OR Q.SHIDAT_0 IS NULL OR Q.SHIDAT_0<>CAST(@EXPEDITION AS datetime)
          OR Q.DSPLINFLG_0<>@REPARTITION_LIGNE
          OR Q.DLVPIO_0<>@PRIORITE_LIVRAISON OR Q.DRN_0<>@TOURNEE))
      THROW 61026,N'Controle des champs de livraison echoue.',1;
   IF EXISTS(SELECT 1 FROM TEST.SORDERQ Q JOIN #L L ON L.LIGNE=Q.SOPLIN_0
      WHERE Q.SOHNUM_0=@NUMERO AND NULLIF(L.FOURNISSEUR,N'') IS NOT NULL
        AND COALESCE(Q.XBPS_0,N'')<>L.FOURNISSEUR COLLATE DATABASE_DEFAULT)
      THROW 61028,N'Controle fournisseur de ligne echoue.',1;
   IF NOT EXISTS(SELECT 1 FROM TEST.SORDER
      WHERE SOHNUM_0=@NUMERO AND APPFLG_0=4 AND HLDSTA_0=1
        AND ORDCLE_0=@ORDCLE_INITIAL AND CHGRAT_0=1)
      THROW 61027,N'Controle des statuts en-tete echoue.',1;
   IF EXISTS(SELECT 1 FROM #L L JOIN TEST.SORDERP P ON P.SOHNUM_0=@NUMERO AND P.SOPLIN_0=L.LIGNE
       WHERE P.VAT_0<>L.TAXE OR P.NETPRINOT_0<>L.PRIX_HT)
      THROW 62013,N'Controle taxes et prix HT des lignes echoue.',1;
   IF EXISTS(SELECT 1 FROM #V V WHERE NOT EXISTS(SELECT 1 FROM TEST.SVCRVAT T WHERE T.VCRNUM_0=@NUMERO AND T.VCRTYP_0=20 AND T.VAT_0=V.TAXE AND T.VATRAT_0=V.RATE AND T.BASTAX_0=V.BASE_HT AND T.AMTTAX_0=V.TAX_AMOUNT))
      THROW 62014,N'Controle ventilation TVA echoue.',1;
   UPDATE TEST.AVALNUM SET VALEUR_0=@COMPTEUR+1
   WHERE CODNUM_0=@TYPE AND SITE_0=@SOCIETE AND PERIODE_0=26 AND VALEUR_0=@COMPTEUR;
   IF @@ROWCOUNT<>1 THROW 61017,N'Compteur non mis a jour.',1;

   COMMIT TRANSACTION;
   SELECT N'INSERTS SQL ET COMMIT EFFECTUES - VALIDATION METIER ET ETAT DES BOUTONS NON GARANTIS' AS RESULTAT,
       @NUMERO AS NUMERO_COMMANDE,@CLIENT AS CLIENT,@TOTAL_HT AS HT,@TVA AS TVA,@TOTAL_TTC AS TTC;
 END;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
DROP TABLE IF EXISTS #M;
DROP TABLE IF EXISTS #L;
DROP TABLE IF EXISTS #V;
